contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint minsum, uint amount, uint am) public payable {
        require(address(this).balance >= amount);
        c.SetMinSum(minsum);
        c.SetLogFile(address(this));
        c.Deposit{value: amount}();
        uint bal = c.balances(address(this));
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
