contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // Set up: point the log at this contract (its fallback accepts AddMessage calls),
        // set MinSum, then initialize the contract so setters are locked.
        c.SetLogFile(address(this));
        c.SetMinSum(1);
        c.Initialized();

        uint balBefore = c.balances(address(this));
        uint etherBefore = address(c).balance;

        // Deposit still works after initialization
        c.Deposit{value: amount}();

        assert(
            c.balances(address(this)) == balBefore + amount &&
            address(c).balance == etherBefore + amount &&
            c.MinSum() == 1
        );
    }

    fallback() external payable {}
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint m, uint amount) public payable {
        require(m > 0);
        require(amount > 0);
        require(address(this).balance >= m);
        c.SetMinSum(m);
        c.Deposit{value: m}();
        c.Initialized();
        uint balBefore = c.balances(address(this));
        uint etherBefore = address(c).balance;
        c.Collect(amount);
        uint balAfter = c.balances(address(this));
        uint etherAfter = address(c).balance;
        if (balBefore >= m && balBefore >= amount) {
            assert(balAfter == balBefore - amount && etherBefore - etherAfter == amount);
        } else {
            assert(balAfter == balBefore && etherAfter == etherBefore);
        }
    }
    receive() external payable {}
}

